--
-- Table structure for table `tasks_task`
--

DROP TABLE IF EXISTS `tasks_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tasks_task` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `notes` longtext,
  `created_at` datetime(6) NOT NULL,
  `due_date` date NOT NULL,
  `is_completed` tinyint(1) NOT NULL,
  `repeat_type` varchar(10) NOT NULL,
  `reminder_days` int unsigned NOT NULL,
  `repeat_interval` int unsigned NOT NULL,
  `is_muted` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `tasks_task_chk_1` CHECK ((`reminder_days` >= 0)),
  CONSTRAINT `tasks_task_chk_2` CHECK ((`repeat_interval` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
